<script setup lang="ts">
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { SettlementDossier } from '@/api/propertySettlements'
import PropertyInstantInput from '@/components/property/PropertyInstantInput.vue'
import PropertyButton from '@/components/property/PropertyButton.vue'
import SettlementPeoplePicker from './SettlementPeoplePicker.vue'
import SettlementDeliveryEditor from './SettlementDeliveryEditor.vue'
import SettlementPersonChangeEditor from './SettlementPersonChangeEditor.vue'
import { blankPersonChange, pendingDelivery } from './dossierForm'
import { settlementInput as input } from './settlementForm'
const props = defineProps<{ supplier: number; labels?: Record<number, string>; periodFrom: string; periodTo: string }>()
const model = defineModel<SettlementDossier>({ required: true }), { t } = useI18n()
const localNames = ref<Record<number, string>>({}), allLabels = computed(() => ({ ...props.labels, ...localNames.value }))
const segments = computed(() => model.value.segments)
function addSegment() { model.value.segments.push({ ordinal: Math.max(0, ...model.value.segments.map(s => s.ordinal)) + 1, valid_from: '', valid_to: '', recipient_ids: [], basis_ref: '', allocation_ref: '' }) }
function recipients(ordinal: number, ids: number[]) { const segment = model.value.segments.find(s => s.ordinal === ordinal)!; segment.recipient_ids = ids; model.value.deliveries = model.value.deliveries.filter(d => d.segment_ordinal !== ordinal || ids.includes(d.recipient_id)); for (const id of ids) if (!model.value.deliveries.some(d => d.segment_ordinal === ordinal && d.recipient_id === id)) model.value.deliveries.push(pendingDelivery(ordinal, id)) }
function remove(ordinal: number) { model.value.segments = model.value.segments.filter(s => s.ordinal !== ordinal); model.value.deliveries = model.value.deliveries.filter(d => d.segment_ordinal !== ordinal) }
</script>
<template><div class="space-y-4" data-section="external-dossier-form"><p class="text-sm text-neutral-500">{{ t('propertySettlements.dossier.help') }} {{ periodFrom }} - {{ periodTo }}</p><div class="grid gap-3 sm:grid-cols-2"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.reference') }}<input v-model="model.ref" required :class="input" data-field="dossier-ref" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.issuer') }}<input v-model="model.issuer.name" required :class="input" data-field="dossier-issuer" /></label><PropertyInstantInput v-model="model.issued_at" :label="t('propertySettlements.dossier.issuedAt')" required /><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.allocation') }}<input v-model="model.allocation_ref" required :class="input" /></label></div><article v-for="segment in segments" :key="segment.ordinal" class="space-y-3 rounded border p-3"><h4>{{ t('propertySettlements.dossier.segment', { number: segment.ordinal }) }}</h4><div class="grid gap-3 sm:grid-cols-2"><PropertyInstantInput v-model="segment.valid_from" :label="t('propertySettlements.dossier.validFrom')" required /><PropertyInstantInput v-model="segment.valid_to" :label="t('propertySettlements.dossier.validTo')" required /><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.recipientBasis') }}<input v-model="segment.basis_ref" required :class="input" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.allocation') }}<input v-model="segment.allocation_ref" required :class="input" /></label></div><SettlementPeoplePicker :model-value="segment.recipient_ids" :supplier="supplier" :labels="allLabels" @update:model-value="recipients(segment.ordinal, $event)" @person-selected="localNames[$event.id] = $event.name" /><template v-for="(delivery, index) in model.deliveries" :key="`${delivery.segment_ordinal}:${delivery.recipient_id}`"><fieldset v-if="delivery.segment_ordinal === segment.ordinal" class="space-y-2 border-t pt-3"><legend>{{ allLabels[delivery.recipient_id] || t('propertySettlements.selectedPerson') }}</legend><SettlementDeliveryEditor v-model="model.deliveries[index]!" :supplier="supplier" :labels="allLabels" /></fieldset></template><PropertyButton icon="trash" variant="danger" @click="remove(segment.ordinal)">{{ t('propertySettlements.remove') }}</PropertyButton></article><PropertyButton icon="plus" @click="addSegment">{{ t('propertySettlements.dossier.addSegment') }}</PropertyButton><section class="space-y-3"><h4>{{ t('propertySettlements.dossier.personChanges') }}</h4><div v-for="(_change, index) in model.person_changes" :key="index" class="space-y-2 rounded border p-3"><SettlementPersonChangeEditor v-model="model.person_changes[index]!" :supplier="supplier" :labels="allLabels" /><PropertyButton icon="trash" variant="danger" @click="model.person_changes.splice(index, 1)">{{ t('propertySettlements.remove') }}</PropertyButton></div><PropertyButton icon="plus" @click="model.person_changes.push(blankPersonChange())">{{ t('propertySettlements.dossier.addChange') }}</PropertyButton></section></div></template>
